<div class="card"><div class="card-header"><h1>Damage / Return Policy</h1><p>Edit return policy for each supply item.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<?php if(!$products):?><p class="muted">No supply items yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Name</th><th>Price</th><th>Current Policy</th><th>Update</th></tr><?php foreach($products as $p):?><tr><td>#<?php echo e($p['id']);?></td><td><?php echo e($p['name']);?></td><td>TK <?php echo e(number_format((float)$p['price'],2));?></td><td class="small"><?php echo $p['return_policy']?e($p['return_policy']):'<span class="muted">— none —</span>';?></td><td><form method="post" action="<?php echo e(url_for('vendor','policy'));?>"><?php echo csrf_field();?><input type="hidden" name="product_id" value="<?php echo e($p['id']);?>"><textarea name="return_policy" rows="2" style="width:260px;"><?php echo e($p['return_policy']);?></textarea><br><button class="btn btn-primary btn-small">Save Policy</button></form></td></tr><?php endforeach;?></table><?php endif;?></div>
